Proof. vm_compute. reflexivity. Qed.

Lemma nrules_sound_1RB1LB_1RC0RB_1LD1RB_1LA0LD : Forall (RuleSound tm false false) nrules.
Proof. apply rule_sound_nil. exact nladder_ok_1RB1LB_1RC0RB_1LD1RB_1LA0LD. Qed.

